  /// < Restart recognition after rejected result
  static const int VC_RECOGNITION_MODE_RESTART_AFTER_REJECT = 1;

  /// < Continuously restart recognition - not support yet
  static const int VC_RECOGNITION_MODE_RESTART_CONTINUOUSLY = 2;

  /// < Start and stop manually without silence
  static const int VC_RECOGNITION_MODE_MANUAL = 3;
}

